// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

// Không cần import Ownable nếu muốn đơn giản tối đa (tạm bỏ qua)
// Nếu muốn có Ownable như mẫu, bạn cần thêm lại: import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AchievementLedger_Minimal
 * @dev Hợp đồng chỉ tập trung vào lưu trữ và truy vấn Thành tựu.
 */
contract AchievementLedger_Minimal {

    // =============================================================
    // STRUCT (Cấu trúc dữ liệu cho một Thành tựu/Bằng cấp)
    // =============================================================

    struct Achievement {
        string title;           
        string achievementType; 
        string institution;     
        uint16 year;            
        string metadataUri;     // Link tới tài liệu xác minh (URL/IPFS Hash)
        uint256 createdAt;      
    }

    // =============================================================
    // STATE VARIABLES & MAPPINGS
    // =============================================================

    // Mapping chính: Địa chỉ Người dùng (address) => Danh sách Thành tựu (Achievement[])
    mapping(address => Achievement[]) public userAchievements;

    // =============================================================
    // EVENTS (Không bắt buộc, nhưng nên có để dễ dàng theo dõi ngoài chuỗi)
    // =============================================================

    event AchievementAdded(
        address indexed user,
        string indexed achievementType,
        string title,
        uint16 year
    );

    // =============================================================
    // FUNCTIONS (Hai hàm chính theo yêu cầu của bạn)
    // =============================================================

    /**
     * @dev (Hàm 1: Thêm Thành tựu - Tương đương POST)
     * Thêm một thành tựu mới vào hồ sơ của người gọi hàm (msg.sender).
     */
    function addAchievement(
        string memory _title,
        string memory _type,
        string memory _institution,
        uint16 _year,
        string memory _metadataUri
    ) external {
        // --- Vùng kiểm tra (Có thể bỏ qua nếu bạn không cần strict checks) ---
        require(bytes(_title).length > 0, "Title cannot be empty");
        require(bytes(_type).length > 0, "Type cannot be empty");
        // Kiểm tra năm không được vượt quá năm hiện tại (Ước tính từ block.timestamp)
        // require(_year <= uint16(block.timestamp / 31536000 + 1970), "Invalid year"); 
        // --------------------------------------------------------------------

        // Thêm dữ liệu vào mảng tương ứng với địa chỉ người gọi
        userAchievements[msg.sender].push(Achievement({
            title: _title,
            achievementType: _type,
            institution: _institution,
            year: _year,
            metadataUri: _metadataUri,
            createdAt: block.timestamp
        }));

        emit AchievementAdded(msg.sender, _type, _title, _year);
    }

    /**
     * @dev (Hàm 2: Truy vấn Thành tựu - Tương đương GET)
     * Trả về danh sách tất cả thành tựu của một địa chỉ cụ thể.
     */
    function getAchievements(address _userAddress)
        external
        view
        returns (Achievement[] memory)
    {
        // Hàm này không cần kiểm tra vì nếu không có thành tựu, nó sẽ trả về mảng rỗng.
        return userAchievements[_userAddress];
    }
}

